#!/bin/bash
set -euo pipefail
echo "==== Fix Abandoned mislabeled as Answered ===="
WEB=/var/www/fusionpbx/app/agent_dashboard
B_CFG=''
B_IN=''
B_RE=''
echo "$B_CFG" | base64 -d > /tmp/skykin_config.php
echo "$B_IN" | base64 -d > /tmp/skykin_inbound.lua
echo "$B_RE" | base64 -d > /tmp/skykin_record_on_agent.lua

docker cp /tmp/skykin_config.php skykin-web:$WEB/skykin_config.php
docker exec skykin-web php -r 'opcache_reset();' 2>/dev/null || true

docker cp /tmp/skykin_inbound.lua skykin-freeswitch:/etc/freeswitch/scripts/skykin_inbound.lua
docker cp /tmp/skykin_record_on_agent.lua skykin-freeswitch:/etc/freeswitch/scripts/skykin_record_on_agent.lua
mkdir -p /opt/skykin/fs-live
cp -f /tmp/skykin_inbound.lua /opt/skykin/fs-live/skykin_inbound.lua
cp -f /tmp/skykin_record_on_agent.lua /opt/skykin/fs-live/skykin_record_on_agent.lua

# Verify PHP labels
docker exec skykin-web php -r '
require "/var/www/fusionpbx/app/agent_dashboard/skykin_config.php";
$abd=["direction"=>"inbound","billsec"=>40,"waitsec"=>0,"last_arg"=>"user/203@ahununu","cc_agent_bridged"=>"","bridge_uuid"=>"","record_name"=>"x.wav"];
$ok=["direction"=>"inbound","billsec"=>90,"waitsec"=>0,"last_arg"=>"user/203@ahununu","cc_agent_bridged"=>"/203@ahununu","bridge_uuid"=>"","record_name"=>"y.wav"];
$ok2=["direction"=>"inbound","billsec"=>90,"waitsec"=>0,"last_arg"=>"user/203@ahununu","cc_agent_bridged"=>"","bridge_uuid"=>"aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee","record_name"=>""];
echo "ring_only=", skykin_cdr_result_label($abd), "\n";
echo "bridged=", skykin_cdr_result_label($ok), "\n";
echo "uuid=", skykin_cdr_result_label($ok2), "\n";
'

echo "DONE — ring/IVR-only (last_arg only) => Abandoned; real connect => Answered"
echo "New agent-answered calls also stamp cc_agent_bridged + start recording."
